   102        else if (!negative && val[k])
   103          break;
   104      }
   105
   106    if ((negative && !(val[k] & 0x80)) || (!negative && (val[k] & 0x80)))
   107      k--;
   108
   109    *len = SIZEOF_UNSIGNED_LONG_INT - k;
